'use strict';
const KEY='niti-storydesk-olympus-tartar-v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function symbols(root=document.body){const shapes={'↗':'M4 20 20 4M5 4h15v15','↥':'M12 20V4m-7 7 7-7 7 7M4 21h16','↙':'M20 4 4 20m0-15v15h15','↓':'M12 3v18m-7-7 7 7 7-7','⛶':'M3 9V3h6m6 0h6v6m0 6v6h-6m-6 0H3v-6','⌖':'M12 2v4m0 12v4M2 12h4m12 0h4M12 6a6 6 0 1 0 0 12 6 6 0 0 0 0-12'};const pattern=/[↗↥↙↓⛶⌖]/;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];let node;while(node=walker.nextNode())if(pattern.test(node.textContent)&&!node.parentElement.closest('script,style,textarea,svg'))nodes.push(node);for(const n of nodes){const f=document.createDocumentFragment();for(const part of n.textContent.split(/([↗↥↙↓⛶⌖])/)){if(shapes[part]){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','symbol');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.5');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',shapes[part]);svg.append(p);f.append(svg);}else f.append(document.createTextNode(part));}n.replaceWith(f);}}
new MutationObserver(records=>{for(const r of records)for(const n of r.addedNodes)if(n.nodeType===1&&!n.matches('svg,.symbol'))symbols(n);}).observe(document.body,{childList:true,subtree:true});
const uid=()=>globalThis.crypto?.randomUUID?.()||'id'+Date.now()+Math.random().toString(16).slice(2);
const icon=(name)=>{const paths={dice:'<path d="m12 2 9 5v10l-9 5-9-5V7Zm0 0L7 15l14-8M3 7l14 8-5 7M7 15h10l-5-13M3 17l4-2m10 0 4 2"/>',overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',scenes:'<path d="M4 4h16v16H4zM4 9h16M8 4l3 5m3-5 3 5"/>',characters:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v2"/>',threads:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="7" r="2"/><circle cx="10" cy="19" r="2"/><path d="m7 5 10 2M6 7l3 10m3 0 6-8"/>',secrets:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',journal:'<path d="M5 3h14v18H5zM9 7h6m-6 5h6m-6 5h3"/>',manuscript:'<path d="M12 5c-4-2-7-2-10 0v15c3-2 6-2 10 0 4-2 7-2 10 0V5c-3-2-6-2-10 0Zm0 0v15"/>'};return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.threads}</svg>`;};
const sections=[['overview','За ширмой'],['session','Связь с игроками'],['scenes','Сцены'],['characters','Персонажи и связи'],['threads','Сюжетные нити'],['secrets','Тайны'],['consequences','Факты и последствия'],['reference','Правила и профили'],['dice','Кубики'],['journal','Журнал сессии'],['manuscript','Рукопись']];
/* Compact labels keep all eleven sections on one line; the full name stays in the tooltip. */
const shortLabels={overview:'Обзор',session:'Связь',characters:'Персонажи',threads:'Нити',consequences:'Последствия',reference:'Правила',journal:'Журнал'};
const initial=()=>structuredClone(window.NITI_MODULE);
let state;let storageOK=true;try{const s=JSON.parse(localStorage.getItem(KEY));state=s&&validState(s)?s:initial();}catch{state=initial();storageOK=false;}
let view=location.hash.slice(1)||'overview',selectedScene=state.current,selectedChar=state.characters[0]?.id,oracle=null,oracleKind='complications',lastFocus=null;
function validState(s){if(!s||s.version!==1||typeof s.title!=='string'||!s.title.trim()||typeof s.manuscript!=='string'||!Number.isInteger(s.session)||s.session<1)return false;const shapes={scenes:['id','title','place','goal','hook','notes','status'],characters:['id','name','role','want','secret'],relations:['id','from','to','label'],threads:['id','title','detail','status'],clocks:['id','title','consequence'],secrets:['id','title','truth','clue'],journal:['id','text','kind','date']};for(const[k,fields]of Object.entries(shapes)){if(!Array.isArray(s[k])||s[k].length>2000||!s[k].every(x=>x&&fields.every(f=>typeof x[f]==='string')&&x.id))return false; if(new Set(s[k].map(x=>x.id)).size!==s[k].length)return false;}return s.clocks.every(c=>Number.isInteger(c.value)&&Number.isInteger(c.max)&&c.max>=2&&c.max<=12&&c.value>=0&&c.value<=c.max)&&s.secrets.every(x=>typeof x.revealed==='boolean')&&s.scenes.every(x=>['ready','active','done'].includes(x.status))&&s.threads.every(x=>['open','later','closed'].includes(x.status))&&(s.current===null||s.scenes.some(x=>x.id===s.current))&&s.relations.every(r=>s.characters.some(c=>c.id===r.from)&&s.characters.some(c=>c.id===r.to))&&validModuleState(s);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#saveStatus').textContent=storageOK?'● Сохранено в браузере':'! Не сохранено · скачай копию';$('#saveStatus').style.color=storageOK?'':'#edba86';}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function record(text,kind='Событие'){state.journal.unshift({id:uid(),date:new Date().toISOString(),text,kind,session:state.session});}
const btn=(label,action,cls='',extra='')=>`<button ${extra.includes('type=')?'':'type="button"'} class="button ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const editBtn=(kind,id)=>`<button class="text-button" data-action="edit" data-kind="${kind}" data-id="${esc(id)}" aria-label="Редактировать">✎</button>`;
const statusLabel=x=>({ready:'Подготовлена',active:'В игре',done:'Завершена',open:'В игре',later:'На потом',closed:'Закрыта'}[x]||x);
function render(){if(!sections.some(s=>s[0]===view))view='overview';$('#nav').innerHTML=sections.map(([id,label])=>`<a href="#${id}" class="nav-item ${id===view?'active':''}" title="${esc(label)}" aria-label="${esc(label)}" ${id===view?'aria-current="page"':''}>${icon(id)}<span>${shortLabels[id]||label}</span>${id==='secrets'?'<span class="nav-count">'+state.secrets.filter(s=>!s.revealed).length+'</span>':''}</a>`).join('');$('#crumb').textContent=sections.find(s=>s[0]===view)[1];document.title=`${sections.find(s=>s[0]===view)[1]} · Нити`;$('#workspace').innerHTML=({overview,session:gmSessionPage,scenes,characters,threads,secrets,journal,manuscript,reference,consequences,dice:dicePage}[view])();$('#saveStatus').textContent=storageOK?'● Сохранено в браузере':'! Не сохранено · скачай копию';window.nitiAnimateNavigation?.(view);window.NitiDesign?.render(view);}
function head(eyebrow,title,subtitle,actions=''){return `<div class="heading-row"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="subtitle">${subtitle}</p></div><div class="header-actions">${actions}</div></div>`;}
function sceneArt(){return `<div class="scene-art industrial-art" aria-hidden="true"><img src="vault-art.svg" alt=""><span class="scene-art-content">OLYMPUS 2207 / ТАРТАР / ЗОНА ДОСТУПА ВЕДУЩЕГО</span></div>`;}

function clock(c){if(c.activation)return moduleClock(c);return `<div class="clock-card"><button class="clock" style="--progress:${c.value/c.max*360}deg" data-action="clock-plus" data-id="${esc(c.id)}" aria-label="Продвинуть угрозу ${esc(c.title)}: ${c.value} из ${c.max}"><span class="clock-inner">${c.value}<small>/${c.max}</small></span></button><div class="clock-copy"><div class="clock-title">${esc(c.title)}</div><div class="clock-label">${c.value===c.max?'Порог достигнут':c.value===0?'Пока тихо':c.max-c.value+' до последствия'}</div><div class="clock-controls"><button data-action="clock-minus" data-id="${esc(c.id)}" aria-label="Уменьшить угрозу">−</button><button data-action="clock-plus" data-id="${esc(c.id)}" aria-label="Продвинуть угрозу">+</button>${editBtn('clocks',c.id)}</div></div></div>`;}
function masterEditorialHero(scene){
  return `<section class="master-hero" aria-labelledby="master-hero-title">
    <div class="master-hero-copy"><p class="master-hero-label">Тартар · Сессия ${state.session}</p><h1 id="master-hero-title">История<br><em>в твоих руках.</em></h1><p class="master-hero-intro">Все сцены, персонажи и решения — в одном месте.</p><div class="master-hero-actions"><a href="#session" class="button primary">Связь с игроками</a>${btn('Завершить сессию','end-session','ghost')}</div></div>
    <div class="master-hero-art" aria-hidden="true"><img data-theme-hero src="assets/power-armor-crimson.webp" alt="" width="960" height="1200" fetchpriority="high"></div>
    <div class="master-current"><span>${scene?'Текущая сцена':'Новая глава'}</span><h2>${scene?esc(scene.title):'История начинается здесь'}</h2><p>${scene?esc(scene.place||'Следующий ход — за тобой.'):'Подготовь первую сцену и собери отряд.'}</p>${scene?btn('Открыть сцену','open-scene','primary',`data-id="${esc(scene.id)}"`):btn('Добавить сцену','add','primary','data-kind="scenes"')}</div>
  </section>`;
}

function overview(){const s=state.scenes.find(s=>s.id===state.current)||state.scenes.find(s=>s.status!=='done');return masterEditorialHero(s)+`<div class="campaign-bar"><span>${state.demo?'<span class="demo-tag">ПРИМЕР</span>':'<span class="demo-tag">ТВОЙ СЮЖЕТ</span>'} ${esc(state.title)}</span><button class="text-button" data-action="campaign">Настроить историю</button></div>${state.nextStart?`<div class="banner"><strong>Начать следующую сессию:</strong> ${esc(state.nextStart)}</div>`:''}<div class="stats-strip">${[[state.scenes.filter(s=>s.status!=='done').length,'сцен впереди','scenes'],[state.characters.length,'персонажей в истории','characters'],[state.threads.filter(t=>t.status!=='closed').length,'нитей на доске','threads'],[state.secrets.filter(s=>!s.revealed).length,'нераскрытых тайн','secrets']].map(([n,t,v])=>`<a href="#${v}" class="stat"><span class="stat-number">${String(n).padStart(2,'0')}</span><span class="stat-label">${t}</span></a>`).join('')}</div>${moduleOverview()}<div class="crimson-section-heading"><span>02 / ПОЛЕВЫЕ ЗАПИСИ<br>РЕШЕНИЯ. УГРОЗЫ. ПОСЛЕДСТВИЯ.</span><h2>МИР НЕ ЖДЁТ.</h2></div><div class="dashboard-grid"><section class="panel scene-panel"><div class="panel-header"><h2 class="panel-title"><span class="tiny-icon">◈</span> Текущая сцена</h2><a class="text-button" href="#scenes">Все сцены</a></div>${s?`${sceneArt()}<div class="scene-feature"><div class="scene-meta"><span class="eyebrow">СЦЕНА ${String(state.scenes.indexOf(s)+1).padStart(2,'0')}</span><span>⌖ ${esc(s.place)}</span></div><h3 class="scene-name">${esc(s.title)}</h3><p class="scene-hook">${esc(modulePublicHook(s))}</p><div class="scene-actions">${btn('Открыть сцену','open-scene','primary',`data-id="${esc(s.id)}"`)}${btn('Режим сцены ⛶','focus','ghost',`data-id="${esc(s.id)}"`)}</div><div class="scene-progress">${state.scenes.map((x,i)=>`<button class="progress-dot ${x.status==='done'?'done':x.id===s.id?'current':''}" data-action="open-scene" data-id="${esc(x.id)}" aria-label="Сцена ${i+1}: ${esc(x.title)}"></button>`).join('')}<span>${state.scenes.filter(x=>x.status==='done').length} из ${state.scenes.length} завершено</span></div></div>`:`<div class="empty-state">${icon('scenes')}<h3>Следующая сцена — твоя.</h3><p>Подготовь место, цель и первую фразу.</p>${btn('＋ Добавить сцену','add','primary','data-kind="scenes"')}</div>`}</section><section class="panel threats-panel"><div class="panel-header"><h2 class="panel-title"><span class="tiny-icon">◷</span> Сценические таймеры</h2><button class="text-button" data-action="add" data-kind="clocks" aria-label="Добавить угрозу">＋</button></div><p class="panel-intro">Точные сроки из модуля. Запускай только при указанном условии; время игры отмечается вручную.</p><div class="clocks-grid">${state.clocks.length?state.clocks.map(clock).join(''):'<div class="empty-state">Добавь угрозу и её последствие.</div>'}</div><div class="threat-foot">Стабилизация раненого останавливает его таймер. Минуты и раунды не смешиваются.</div></section><section class="panel"><div class="panel-header"><h2 class="panel-title">Сюжетные нити <span class="badge">${state.threads.filter(t=>t.status!=='closed').length}</span></h2><a class="text-button" href="#threads">Все нити</a></div><div class="thread-list">${state.threads.filter(t=>t.status!=='closed').slice(0,3).map(t=>`<a href="#threads" class="thread-row"><span class="thread-dot"></span><div class="thread-copy"><div class="thread-title">${esc(t.title)}</div><div class="thread-sub">${esc(t.detail)}</div></div><span></span></a>`).join('')||'<div class="empty-state">У каждой истории есть незакрытый вопрос.</div>'}</div></section><section class="panel oracle-panel"><div class="panel-header"><h2 class="panel-title"><span class="tiny-icon">✧</span> Если всё пошло не по плану</h2><span class="tag">ИДЕИ ВНЕ МОДУЛЯ</span></div><div id="oracleBody">${oracleHTML()}</div></section><section class="panel quick-note-panel"><div class="panel-header"><h2 class="panel-title">На полях</h2><a class="text-button" href="#journal">Журнал</a></div><form id="quickNote" class="note-form"><label class="sr-only" for="quickNoteText">Решение или заметка</label><textarea id="quickNoteText" class="textarea" name="text" rows="2" required maxlength="10000" placeholder="Герои решили… Мир ответит на это…"></textarea>${btn('Запомнить','submit-note','primary small','type="submit"')}</form></section></div>`;}
function oracleHTML(){return oracle?`<div class="oracle-title">${esc(oracle.title)}</div><p class="oracle-copy">${esc(oracle.body)}</p><p class="oracle-question">${esc(oracle.question)}</p><div class="oracle-actions">${btn('Ещё вариант','oracle-again','ghost small')}${btn('Взять в заметки','oracle-save','primary small')+btn(oracleKind==='worldMoves'?'Поворот':'Ход мира',oracleKind==='worldMoves'?'oracle':'world','ghost small')}</div>`:`<div class="oracle-title">История умеет удивлять.<br>Даже ведущего.</div><p class="oracle-copy">Вытащи идею для поворота или узнай, что изменилось за кадром.</p><div class="oracle-actions">${btn('✧ Вытянуть поворот','oracle','primary small')}${btn('Ход мира','world','ghost small')}</div>`;}
function scenes(){let s=state.scenes.find(x=>x.id===selectedScene)||state.scenes.find(x=>x.id===state.current)||state.scenes[0];return head('ПУТЬ ИСТОРИИ','Сцены','Подготовь ситуацию. Оставь героям право изменить исход.',btn('＋ Новая сцена','add','primary','data-kind="scenes"'))+`<div class="split-layout"><div class="list-stack">${state.scenes.map((x,i)=>`<button class="scene-list-card ${s?.id===x.id?'active':''}" data-action="select-scene" data-id="${esc(x.id)}"><span class="scene-number">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(x.title)}</strong><small>${x.act?esc(x.act)+' · ':''}${esc(x.place)} · ${statusLabel(x.status)}</small></div><span></span></button>`).join('')||empty('Пока чистая страница. Добавь первую сцену.','scenes')}</div>${s?`<section class="panel scene-detail"><div class="panel-header"><span class="tag">${statusLabel(s.status)}</span>${editBtn('scenes',s.id)}</div><h2 class="scene-name">${esc(s.title)}</h2><div class="muted">⌖ ${esc(s.place)}</div><div class="field"><div class="field-label">ПЕРВАЯ ФРАЗА</div><p class="scene-hook">${esc(modulePublicHook(s))}</p></div><div class="field"><div class="field-label">ЧТО ЗДЕСЬ НА КОНУ</div><p>${esc(s.goal)}</p></div>${moduleSceneDetails(s)}<details class="source-notes"><summary>Полный текст задания · заметки ведущего</summary><p class="prewrap">${esc(s.notes)}</p></details><div class="scene-actions">${btn('⛶ Показать сцену','focus','ghost',`data-id="${esc(s.id)}"`)}${s.status==='done'?btn('Вернуть в подготовку','reopen-scene','ghost',`data-id="${esc(s.id)}"`):s.id===state.current?btn('Завершить сцену ✓','complete-scene','primary',`data-id="${esc(s.id)}"`):btn('Сделать текущей','activate-scene','primary',`data-id="${esc(s.id)}"`)}</div></section>`:''}</div>`;}
function empty(text,kind){return `<div class="empty-state"><p>${text}</p>${kind?btn('＋ Добавить','add','ghost',`data-kind="${kind}"`):''}</div>`;}
function characters(){const c=state.characters.find(x=>x.id===selectedChar)||state.characters[0];return head('У КАЖДОГО ЕСТЬ МОТИВ','Люди между строк.','Помни, чего они хотят. И о чём предпочитают молчать.',btn('＋ Персонаж','add','primary','data-kind="characters"'))+`${modulePeopleDirectory()}<section class="panel"><div class="panel-header"><h2 class="panel-title">Карта связей выбранного персонажа</h2>${btn('＋ Связь','add-relation','ghost small')}</div><div class="graph-wrap">${graph()}</div><p class="graph-hint">Выбери персонажа в списке или на карте. Здесь показаны его прямые связи; полные условия перечислены ниже.</p></section>${c?`<div class="split-layout character-details"><section class="panel entity-card"><div class="card-top"><span class="avatar">${esc(c.name.slice(0,1))}</span>${editBtn('characters',c.id)}</div><h2 class="card-title">${esc(c.name)}</h2><p class="muted">${esc(c.role)}</p><div class="field"><div class="field-label">ХОЧЕТ</div><p>${esc(c.want)}</p></div><details><summary>Тайна персонажа · только для ведущего</summary><p class="prewrap">${esc(c.secret)}</p></details>${moduleCharacterExtra(c)}</section><section class="panel"><div class="panel-header"><h2 class="panel-title">Его нити</h2></div><div class="relation-list">${state.relations.filter(r=>r.from===c.id||r.to===c.id).map(r=>`<div class="relation-row ${r.confirmed?'is-confirmed':''}"><span>${r.confirmed?'<small class="relation-confirmed-badge">Подтверждено в игре</small>':''}${esc(state.characters.find(x=>x.id===r.from)?.name)} <span class="muted">— ${esc(r.label)} —</span> ${esc(state.characters.find(x=>x.id===r.to)?.name)}${r.source?'<small class="relation-source">'+esc(r.source)+'</small>':''}</span><button class="text-button" data-action="delete-relation" data-id="${esc(r.id)}" aria-label="Удалить связь">×</button></div>`).join('')||empty('Связи ещё не обозначены.')}</div></section></div>`:empty('Первый персонаж ждёт своего имени.','characters')}`;}
function graph(){const selected=state.characters.find(x=>x.id===selectedChar)||state.characters[0];if(!selected)return empty('Добавь персонажей, чтобы увидеть связи.');const rel=state.relations.filter(r=>r.from===selected.id||r.to===selected.id);const ids=new Set([selected.id,...rel.flatMap(r=>[r.from,r.to])]);const chars=state.characters.filter(c=>ids.has(c.id)),n=chars.length,width=900,height=Math.max(320,Math.ceil(n/5)*150);const pts=chars.map((c,i)=>({...c,x:n<=6?450+Math.cos(-Math.PI/2+i/n*Math.PI*2)*Math.min(300,n*75):90+(i%5)*180,y:n<=6?height/2+Math.sin(-Math.PI/2+i/n*Math.PI*2)*100:65+Math.floor(i/5)*150}));return `<svg viewBox="0 0 ${width} ${height}" role="group" aria-label="Прямые связи выбранного персонажа">${rel.map(r=>{const a=pts.find(p=>p.id===r.from),b=pts.find(p=>p.id===r.to);if(!a||!b)return'';return `<g class="relation-edge ${r.confirmed?'is-confirmed':''}"><title>${esc(a.name)} — ${esc(r.label)} — ${esc(b.name)}${r.confirmed?' · подтверждено в игре':''}</title><path d="M${a.x} ${a.y} L${b.x} ${b.y}" fill="none" stroke="#a9ae9d" stroke-width="1.5" stroke-dasharray="4 5"/></g>`;}).join('')}${pts.map(c=>`<g class="graph-node ${c.id===selected.id?'selected':''}" role="button" tabindex="0" data-action="select-char" data-id="${esc(c.id)}" aria-label="Открыть персонажа ${esc(c.name)}"><circle cx="${c.x}" cy="${c.y}" r="25"/><text x="${c.x}" y="${c.y+6}" text-anchor="middle" class="graph-initial">${esc(c.name.slice(0,1))}</text><rect x="${c.x-86}" y="${c.y+31}" width="172" height="40" rx="4" fill="#f4f2e9"/><text x="${c.x}" y="${c.y+49}" text-anchor="middle" class="graph-name">${esc(c.name.slice(0,21))}</text>${c.name.length>21?`<text x="${c.x}" y="${c.y+64}" text-anchor="middle" class="graph-name">${esc(c.name.slice(21,42))}</text>`:''}</g>`).join('')}</svg>`;}

function threads(){return head('НИ ОДИН ВЫБОР НЕ ИСЧЕЗАЕТ','Сюжетные нити','Вопросы, обещания и последствия, которые ещё отзовутся.',btn('＋ Новая нить','add','primary','data-kind="threads"'))+`<div class="kanban">${[['open','В игре'],['later','На потом'],['closed','Закрыто']].map(([status,label])=>`<section class="kanban-column"><div class="kanban-title">${label}<span class="badge">${state.threads.filter(t=>t.status===status).length}</span></div>${state.threads.filter(t=>t.status===status).map(t=>`<article class="thread-card"><div class="card-top"><span class="thread-dot"></span>${editBtn('threads',t.id)}</div><h2 class="card-title">${esc(t.title)}</h2><p class="card-body">${esc(t.detail)}</p><label class="field-label" for="thread-${esc(t.id)}">СТАТУС</label><select class="input" id="thread-${esc(t.id)}" data-thread="${esc(t.id)}">${['open','later','closed'].map(v=>`<option value="${v}" ${v===status?'selected':''}>${statusLabel(v)}</option>`).join('')}</select></article>`).join('')||'<p class="muted kanban-empty">Здесь пока тихо.</p>'}</section>`).join('')}</div>`;}
function secrets(){return head('ПО ЭТУ СТОРОНУ ШИРМЫ','Правда под поверхностью.','Отделяй то, что знаешь ты, от того, что уже узнали герои.',btn('＋ Новая тайна','add','primary','data-kind="secrets"'))+`<div class="card-grid">${state.secrets.map(x=>`<article class="panel secret-card"><div class="card-top"><span class="tag">${x.revealed?'РАСКРЫТО':'ЗА ШИРМОЙ'}</span>${editBtn('secrets',x.id)}</div><h2 class="card-title">${esc(x.title)}</h2><div class="field"><div class="field-label">УЛИКА ДЛЯ ГЕРОЕВ</div><p>${esc(x.clue)}</p></div><details ${x.revealed?'open':''}><summary>${x.revealed?'Истина':'Показать истину ведущему'}</summary><p class="prewrap">${esc(x.truth)}</p></details><div class="card-footer">${btn(x.revealed?'Вернуть за ширму':'Герои узнали правду ✓','toggle-secret',x.revealed?'ghost small':'primary small',`data-id="${esc(x.id)}"`)}</div></article>`).join('')||empty('Что на самом деле происходит в твоей истории?','secrets')}</div>`;}
function journal(){return head('ПАМЯТЬ ИСТОРИИ','То, что уже случилось.','Решения героев и ответы мира. Всё, что стоит унести в следующую сессию.',btn(' Скачать журнал','journal-export','ghost'))+`<section class="panel"><div class="panel-header"><h2 class="panel-title">Новая запись</h2><span class="tag">СЕССИЯ ${state.session}</span></div><form class="note-form" id="journalForm"><label class="sr-only" for="journalText">Текст записи</label><textarea class="textarea" id="journalText" name="text" rows="3" required maxlength="20000" placeholder="Какое решение приняли герои? Что изменилось в мире?"></textarea><div class="scene-actions"><label class="sr-only" for="noteKind">Тип записи</label><select id="noteKind" class="input" name="kind"><option>Решение</option><option>Последствие</option><option>Заметка</option></select><button class="button primary" type="submit">Запомнить</button></div></form></section><div class="journal-list">${state.journal.map(j=>`<article class="journal-item"><div class="journal-time">${esc(new Date(j.date).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))}<span>Сессия ${j.session||1}</span></div><div class="journal-content"><span class="tag">${esc(j.kind)}</span><p class="prewrap">${esc(j.text)}</p></div><button class="text-button" data-action="delete-journal" data-id="${esc(j.id)}" aria-label="Удалить запись">×</button></article>`).join('')||empty('Пока ничего не записано. У истории хорошая память — если ей немного помочь.')}</div>`;}
function manuscript(){return head('С ЧЕГО ВСЁ НАЧАЛОСЬ','Твоя рукопись.','Держи исходный текст рядом с живой историей.',btn(' Открыть .txt / .md','story-file','ghost'))+`${state.demo?'<div class="banner"><strong>Сейчас открыт пример.</strong> Это вымышленная история для знакомства с пультом. Вставь свой сюжет ниже или начни чистую историю.</div>':''}<section class="panel manuscript"><form id="manuscriptForm"><label class="field-label" for="storyTitle">НАЗВАНИЕ ИСТОРИИ</label><input id="storyTitle" name="title" class="input" required maxlength="200" value="${esc(state.title)}"><label class="field-label" for="storyText">ИСХОДНЫЙ ТЕКСТ</label><textarea id="storyText" name="text" class="textarea manuscript-text" rows="18" maxlength="1000000" placeholder="Вставь текст сюжета сюда…">${esc(state.manuscript)}</textarea><label class="checkbox-label"><input type="checkbox" name="fromHeadings"> Добавить сцены из заголовков Markdown (# и ##)</label><p class="muted">Текст сохраняется как есть. Заголовки можно превратить в заготовки сцен, персонажей и тайны ты задаёшь сам.</p><div class="scene-actions"><button class="button primary" type="submit">Сохранить рукопись</button>${btn('Начать чистую историю','new-story','ghost')}</div></form></section>${moduleRestorePanel()}<section class="panel settings-panel"><div class="panel-header"><h2 class="panel-title">Твоя история остаётся у тебя.</h2></div><p>Изменения хранятся в этом браузере. Для переноса на другое устройство скачай резервную копию. Очистка данных браузера удалит локальные записи.</p><div class="scene-actions">${btn(' Скачать копию','backup','ghost')}${btn(' Восстановить из JSON','restore','ghost')}</div></section>`;}
function navigate(v){if(location.hash.slice(1)!==v)location.hash=v;else{view=v;render();}}
window.addEventListener('hashchange',()=>{view=location.hash.slice(1);render();window.scrollTo(0,0);});
function modal(title,body,onSubmit,footer='',large=false){lastFocus=document.activeElement;$('#modalRoot').innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="modalTitle" class="modal ${large?'large':''}"><div class="modal-header"><h2 id="modalTitle">${title}</h2><button class="close-button" data-action="close-modal" aria-label="Закрыть">×</button></div><form id="dialogForm"><div class="modal-body">${body}</div><div class="modal-footer">${footer||btn('Отмена','close-modal','ghost')+'<button class="button primary" type="submit">Сохранить</button>'}</div></form></section></div>`;document.body.style.overflow='hidden';$('#dialogForm').onsubmit=e=>{e.preventDefault();onSubmit(new FormData(e.currentTarget));};setTimeout(()=>$('#modalRoot').querySelector('input,textarea,select,button')?.focus(),30);}
function closeModal(){$('#modalRoot').innerHTML='';document.body.style.overflow='';lastFocus?.focus();}
function field(key,label,value='',type='input',required=false,options=[]){let control=type==='textarea'?`<textarea class="textarea" id="f-${key}" name="${key}" rows="3" maxlength="20000" ${required?'required':''}>${esc(value)}</textarea>`:type==='select'?`<select class="input" id="f-${key}" name="${key}">${options.map(([k,l])=>`<option value="${esc(k)}" ${k===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select>`:`<input class="input" id="f-${key}" name="${key}" value="${esc(value)}" maxlength="300" ${required?'required':''}>`;return `<div class="field"><label class="field-label" for="f-${key}">${label}</label>${control}</div>`;}
const schemas={scenes:{title:'Сцена',fields:[['title','Название','input',true],['place','Место'],['playerTitle','Заголовок для игроков'],['playerPlace','Место для игроков'],['hook','Первая фраза · можно показать героям','textarea'],['goal','Что на кону','textarea'],['notes','Заметки только для ведущего','textarea']]},characters:{title:'Персонаж',fields:[['name','Имя','input',true],['role','Роль в истории'],['want','Чего хочет','textarea'],['secret','Что скрывает','textarea']]},threads:{title:'Сюжетная нить',fields:[['title','Открытый вопрос','input',true],['detail','Зацепки и возможные последствия','textarea']]},clocks:{title:'Угроза',fields:[['title','Что приближается','input',true],['consequence','Что случится, когда часы заполнятся','textarea',true],['max','Число шагов','select',true]]},secrets:{title:'Тайна',fields:[['title','Название','input',true],['clue','Улика для героев','textarea'],['truth','Скрытая истина','textarea',true]]}};
function editor(kind,id){const schema=schemas[kind];if(!schema)return;const old=state[kind].find(x=>x.id===id);const defaults={scenes:{place:'',goal:'',hook:'',notes:'',status:'ready'},characters:{role:'',want:'',secret:'',color:'moss'},threads:{detail:'',status:'open'},clocks:{max:6,value:0,consequence:''},secrets:{truth:'',clue:'',revealed:false}};const obj=old||{...defaults[kind]};modal(`${old?'Редактировать':'Добавить'} · ${schema.title}`,schema.fields.map(([k,l,t,r])=>field(k,l,obj[k]??'',t||'input',r,k==='max'?[2,3,4,6,8,10,12].map(x=>[String(x),String(x)]):[])).join(''),f=>{const data={...obj,id:old?.id||uid()};for(const[k]of schema.fields)data[k]=k==='max'?Number(f.get(k)):String(f.get(k)||'').trim();if(!data[schema.fields[0][0]]){toast('Название не может быть пустым.');return;}if(kind==='clocks')data.value=Math.min(data.value,data.max);if(old)state[kind]=state[kind].map(x=>x.id===id?data:x);else{state[kind].push(data);if(kind==='scenes'&&!state.current){state.current=data.id;data.status='active';}if(kind==='characters')selectedChar=data.id;}save();closeModal();render();toast('Сохранено.');},(old?btn('Удалить','delete-entity','danger',`data-kind="${kind}" data-id="${esc(id)}"`):'')+btn('Отмена','close-modal','ghost')+'<button class="button primary" type="submit">Сохранить</button>');}
function confirmDialog(title,text,action,label='Подтвердить'){modal(title,`<p>${esc(text)}</p>`,()=>{action();closeModal();render();},btn('Отмена','close-modal','ghost')+`<button class="button primary" type="submit">${label}</button>`);}
function newStory(title='Новая история',text=''){state={version:1,title:title.trim()||'Новая история',demo:false,session:1,current:null,scenes:[],characters:[],relations:[],threads:[],clocks:[],secrets:[],journal:[],manuscript:text,nextStart:''};selectedScene=null;selectedChar=null;oracle=null;save();}
function download(name,text,type='application/json'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function sceneAction(id,mode){const s=state.scenes.find(x=>x.id===id);if(!s)return;if(mode==='complete'){s.status='done';record('Завершена сцена: '+s.title,'Сцена');const next=state.scenes.find(x=>x.status!=='done');state.current=next?.id||null;if(next)next.status='active';selectedScene=next?.id||s.id;}else if(mode==='reopen'){s.status='ready';if(!state.current){state.current=s.id;s.status='active';}}else{state.scenes.forEach(x=>{if(x.status==='active')x.status='ready';});s.status='active';state.current=s.id;record('Начата сцена: '+s.title,'Сцена');}save();render();if(mode==='active')gmSessionMissionSelected(id);}
function focusScene(id){const s=state.scenes.find(x=>x.id===id);if(!s)return;lastFocus=document.activeElement;$('#focusRoot').innerHTML=`<section class="focus-mode" role="dialog" aria-modal="true" aria-label="Режим сцены"><div class="focus-controls"><span>НИТИ · РЕЖИМ СЦЕНЫ</span><button class="button ghost" data-action="close-focus">Закрыть · Esc</button></div><div class="focus-content"><div class="focus-eyebrow">${esc(s.playerPlace||s.place)}</div><h1 class="focus-title">${esc(s.playerTitle||s.title)}</h1><p class="focus-text">${esc(modulePublicHook(s))}</p><span class="focus-ornament">✧</span></div><div class="focus-foot">В этой сцене всё ещё возможно.</div></section>`;document.body.style.overflow='hidden';$('#focusRoot button').focus();}
function closeFocus(){$('#focusRoot').innerHTML='';document.body.style.overflow='';lastFocus?.focus();}
function advanceClock(id,delta){const c=state.clocks.find(x=>x.id===id);if(!c)return;if(c.activation&&!c.active&&delta>0){toast('Сначала запусти таймер при указанном условии.');return;}const before=c.value;c.value=Math.max(0,Math.min(c.max,c.value+delta));if(c.value===before)return;const milestone=c.steps?.find(x=>x.at===c.value);if(delta>0&&milestone)record(c.title+': '+milestone.label,'Отметка таймера');if(c.value===c.max){if(c.activation)c.active=false;record('Достигнут срок: '+c.title+'. '+c.consequence,'Таймер');save();render();modal('Достигнута отметка времени.',`<div class="eyebrow">${esc(c.title)}</div><p class="scene-hook">${esc(c.consequence)}</p><p class="muted">Отметка записана в журнал. Примени последствие по условиям модуля.</p>`,()=>closeModal(),'<button class="button primary" type="submit">Вернуться за ширму</button>');}else{save();render();if(delta>0&&milestone)toast(milestone.label);}}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,kind=b.dataset.kind;const actions={manuscript:()=>navigate('manuscript'),add:()=>editor(kind),edit:()=>editor(kind,id),'close-modal':closeModal,'close-focus':closeFocus,'open-scene':()=>{selectedScene=id;navigate('scenes');gmSessionMissionSelected(id);},'select-scene':()=>{selectedScene=id;render();gmSessionMissionSelected(id);},'select-char':()=>{selectedChar=id;render();},focus:()=>focusScene(id),'activate-scene':()=>sceneAction(id,'active'),'complete-scene':()=>sceneAction(id,'complete'),'reopen-scene':()=>sceneAction(id,'reopen'),'clock-plus':()=>advanceClock(id,1),'clock-minus':()=>advanceClock(id,-1),oracle:()=>{oracleKind='complications';actions['oracle-again']();},'oracle-again':()=>{const list=STORY_PROMPTS[oracleKind];const pool=list.filter(x=>x.id!==oracle?.id);oracle=pool[Math.floor(Math.random()*pool.length)];$('#oracleBody').innerHTML=oracleHTML();},world:()=>{oracleKind='worldMoves';actions['oracle-again']();},'oracle-save':()=>{if(!oracle)return;record(oracle.title+'\n'+oracle.body+'\n'+oracle.question,'Идея, не факт');save();toast('Идея записана в журнал.');},'toggle-secret':()=>{const x=state.secrets.find(x=>x.id===id);x.revealed=!x.revealed;record((x.revealed?'Герои узнали тайну: ':'Тайна возвращена за ширму: ')+x.title,'Тайна');save();render();},backup:()=>{download('niti-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2));toast('Копия скачана. Храни её вместе с рукописью.');},restore:()=>$('#backupFile').click(),'story-file':()=>$('#storyFile').click(),'journal-export':()=>download('niti-session-journal.md',`# ${state.title}\n\n`+state.journal.slice().reverse().map(j=>`## ${j.kind} · сессия ${j.session||1}\n${new Date(j.date).toLocaleString('ru-RU')}\n\n${j.text}\n`).join('\n'),'text/markdown'),'new-story':()=>confirmDialog('Начать новую историю?','Текущая история в этом браузере будет заменена. Сначала скачай резервную копию, если хочешь её сохранить.',()=>{newStory();},'Начать с чистого листа'),'delete-entity':()=>confirmDialog('Удалить запись?','Запись будет удалена. Для персонажа также удалятся его связи.',()=>{state[kind]=state[kind].filter(x=>x.id!==id);if(kind==='characters')state.relations=state.relations.filter(x=>x.from!==id&&x.to!==id);if(kind==='scenes'&&state.dependencies)state.dependencies=state.dependencies.filter(d=>d.from!==id&&d.to!==id);if(kind==='scenes'&&state.current===id){state.current=state.scenes.find(x=>x.status!=='done')?.id||null;if(state.current)state.scenes.find(x=>x.id===state.current).status='active';}save();},'Удалить'),'delete-relation':()=>confirmDialog('Удалить связь?','Персонажи останутся в истории.',()=>{state.relations=state.relations.filter(r=>r.id!==id);save();},'Удалить'),'delete-journal':()=>confirmDialog('Удалить запись из журнала?','Это действие уберёт только выбранную запись.',()=>{state.journal=state.journal.filter(x=>x.id!==id);save();},'Удалить'),'add-relation':()=>{if(state.characters.length<2){toast('Для связи нужны хотя бы два персонажа.');return;}const opts=state.characters.map(c=>[c.id,c.name]);modal('Новая связь',field('from','От кого',opts[0][0],'select',true,opts)+field('to','К кому',opts[1][0],'select',true,opts)+field('label','Что их связывает','','input',true),f=>{if(f.get('from')===f.get('to')){toast('Выбери двух разных персонажей.');return;}const label=String(f.get('label')).trim();if(!label){toast('Опиши связь.');return;}state.relations.push({id:uid(),from:f.get('from'),to:f.get('to'),label});save();closeModal();render();});},campaign:()=>modal('Название истории',field('title','Название',state.title,'input',true),f=>{const title=String(f.get('title')).trim();if(!title){toast('Введи название.');return;}state.title=title;save();closeModal();render();}),'end-session':()=>gmEndSession(),help:()=>modal('Добро пожаловать за ширму.',`<p><strong>1. Принеси свою историю.</strong> В «Рукописи» вставь текст или открой .txt / .md. Сейчас загружен модуль «Тартар» из твоего файла: 14 заданий с проверками, связями и наградами.</p><p><strong>2. Подготовь опоры.</strong> Добавь сцены, мотивы персонажей, тайны и часы угроз. Всё можно менять.</p><p><strong>3. Веди свободно.</strong> Открывай сцену без секретов, записывай решения и двигай часы, когда это логично для мира.</p><p><strong>4. Сохрани продолжение.</strong> Заверши сессию и скачай резервную копию. Подготовка и заметки хранятся в этом браузере. Выбранная миссия и выданные через общую сессию награды синхронизируются с игроками. Во вкладке «Факты и последствия» вручную отмечай исходы; завершение сцены не выдаёт опыт автоматически.</p><p class="muted">Повороты — отдельная необязательная колода идей. Они не заменяют содержание модуля и попадают в журнал как идеи, не факты.</p>`,()=>closeModal(),'<button class="button primary" type="submit">Я за ширмой</button>')};if(actions[a])actions[a]();else moduleAction(a,id,b);});
document.addEventListener('submit',e=>{if(e.target.id==='quickNote'||e.target.id==='journalForm'){e.preventDefault();const f=new FormData(e.target),text=String(f.get('text')).trim();if(!text){toast('Сначала запиши мысль.');return;}record(text,f.get('kind')||'Заметка');save();e.target.reset();toast('История запомнила.');if(view==='journal')render();}if(e.target.id==='manuscriptForm'){e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')).trim();if(!title){toast('У истории должно быть название.');return;}const text=String(f.get('text')||'');const apply=()=>{state.title=title;state.manuscript=text;state.demo=false;let count=0;if(f.has('fromHeadings')){const parts=text.split(/^(#{1,2})\s+(.+)$/gm);for(let i=1;i<parts.length;i+=3){const title=parts[i+1].trim(),notes=(parts[i+2]||'').trim();state.scenes.push({id:uid(),title,place:'',goal:'',hook:notes.split(/\n\s*\n/)[0]?.slice(0,1500)||'',notes,status:'ready'});count++;}if(!state.current&&state.scenes.length){state.current=state.scenes[0].id;state.scenes[0].status='active';}}save();render();toast('Рукопись сохранена.'+(count?' Добавлено сцен: '+count+'.':''));};if(state.demo){confirmDialog('Заменить пример своим сюжетом?','Демонстрационные сцены, персонажи, тайны и журнал будут очищены. Текст из формы станет рукописью новой истории.',()=>{newStory(title,text);apply();},'Загрузить мою историю');}else apply();}});
document.addEventListener('change',e=>{if(e.target.dataset.thread){const t=state.threads.find(x=>x.id===e.target.dataset.thread);if(!t)return;t.status=e.target.value;record('Нить «'+t.title+'»: '+statusLabel(t.status),'Нить');save();render();}});
$('#storyFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2000000){toast('Файл слишком большой. Выбери текст до 2 МБ.');return;}try{const text=await f.text();navigate('manuscript');setTimeout(()=>{$('#storyText').value=text;$('#storyTitle').value=f.name.replace(/\.(txt|md)$/i,'');toast('Текст открыт. Нажми «Сохранить рукопись».');},30);}catch{toast('Не удалось прочитать файл.');}e.target.value='';});
$('#backupFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error();const data=JSON.parse(await f.text());if(!validState(data))throw Error();confirmDialog('Восстановить историю?',`«${data.title}» заменит текущую историю в этом браузере.`,()=>{state=data;selectedScene=state.current;selectedChar=state.characters[0]?.id;oracle=null;save();toast('История восстановлена.');},'Восстановить');}catch{toast('Не удалось открыть копию. Нужен JSON, скачанный из «Нитей».');}e.target.value='';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#focusRoot').children.length)closeFocus();else if($('#modalRoot').children.length)closeModal();}if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('graph-node')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}const root=$('#focusRoot').children.length?$('#focusRoot'):$('#modalRoot').children.length?$('#modalRoot'):null;if(e.key==='Tab'&&root){const els=[...root.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);if(els.length){const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}});
render();symbols();if(storageOK)save();
